/* Maquette 2026-11 : sections de la maquette sur l'accueil et A propos (HTML encode en base64, styles sous .ghm) */
(function(){
var D={"jumpHome_fr": "", "sejour_fr": "", "homeAfter_fr": "", "jumpAbout_fr": "", "aboutAfter_fr": "", "jumpHome_en": "", "sejour_en": "", "homeAfter_en": "", "jumpAbout_en": "", "aboutAfter_en": "", "css": ""};
function dec(k){return decodeURIComponent(escape(atob(D[k])));}
function info(){var raw=location.pathname;try{raw=decodeURIComponent(raw);}catch(e){}var fr=raw.indexOf("/fr")===0;var p=raw.replace(/^\/fr/,"").replace(/\/$/,"");return {fr:fr,p:p,l:fr?"fr":"en"};}
function css(){if(document.getElementById("ghm-css"))return;var s=document.createElement("style");s.id="ghm-css";s.textContent=dec("css");document.head.appendChild(s);}
function wrapEl(html){var d=document.createElement("div");d.className="ghm";d.innerHTML=html;return d;}
function block(el){var m=document.querySelector("main")||document.body;var b=el;while(b&&b.parentElement&&b.parentElement!==m)b=b.parentElement;return b&&b.parentElement===m?b:null;}
function findH(re){var hs=document.querySelectorAll("main h1, main h2");for(var i=0;i<hs.length;i++){if(re.test(hs[i].textContent))return hs[i];}return null;}
function headH(){var h=document.querySelector("header");var v=h?Math.round(h.getBoundingClientRect().height):0;var pos=h?getComputedStyle(h).position:"";document.documentElement.style.setProperty("--gh-head",(pos==="fixed"||pos==="sticky")?v+"px":"0px");}
function runScripts(root){var ss=root.querySelectorAll("script");for(var i=0;i<ss.length;i++){var o=ss[i];var n=document.createElement("script");n.textContent=o.textContent;o.parentNode.replaceChild(n,o);}}
function home(i){
  if(document.getElementById("ghm-home"))return;
  var hv=findH(/^(En vedette|Featured)$/);var hs=findH(/(bien au-del|well beyond)/);
  if(!hv||!hs)return;
  var bv=block(hv),bs=block(hs);if(!bv||!bs)return;
  css();headH();
  bv.id="proprietes";
  var j=wrapEl(dec("jumpHome_"+i.l));j.id="ghm-jump";bv.parentNode.insertBefore(j,bv);
  var s=wrapEl(dec("sejour_"+i.l)+dec("homeAfter_"+i.l));s.id="ghm-home";
  bs.style.display="none";bs.parentNode.insertBefore(s,bs.nextSibling);
}
function about(i){
  if(document.getElementById("ghm-about"))return;
  var m=document.querySelector("main");if(!m)return;
  var img=null,imgs=m.querySelectorAll("img");for(var k=0;k<imgs.length;k++){if(/pkQtASIabFA|Mika/i.test(imgs[k].src+imgs[k].alt)){img=imgs[k];break;}}
  if(!img)return;var b=block(img);if(!b)return;
  css();headH();
  b.id="mikael";
  var j=wrapEl(dec("jumpAbout_"+i.l));j.id="ghm-jump";b.parentNode.insertBefore(j,b);
  var s=wrapEl(dec("aboutAfter_"+i.l));s.id="ghm-about";b.parentNode.insertBefore(s,b.nextSibling);
  runScripts(s);
}
function run(){try{var i=info();if(i.p==="")home(i);else if(i.p==="/about-us")about(i);}catch(e){}}
if(document.readyState!=="loading")run();document.addEventListener("DOMContentLoaded",run);
var k=0,iv=setInterval(function(){run();if(++k>60)clearInterval(iv);},250);
if(window.MutationObserver){var q;new MutationObserver(function(){clearTimeout(q);q=setTimeout(run,150);}).observe(document.documentElement,{childList:true,subtree:true});}
})();
